const addQuestion = async () => {
  if (!newQuestion.trim()) return;
  const payload = {
    question_text: newQuestion,
    is_choice_based: questionType === 'choice',
    is_rating_based: questionType === 'rating'
  };
  console.log('Отправляемый payload:', payload);
  const response = await fetch('http://localhost:3001/api/admin/questions', { // Изменил маршрут
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });
  const result = await response.json();
  console.log('Ответ сервера:', result);
  if (result.success) {
    setNewQuestion('');
    fetchQuestions();
  }
};

const deleteQuestion = async (id) => {
  console.log('Удаление вопроса с ID:', id);
  const response = await fetch(`http://localhost:3001/api/admin/questions/${id}`, { // Изменил маршрут
    method: 'DELETE'
  });
  const result = await response.json();
  console.log('Результат удаления:', result);
  if (result.success) {
    fetchQuestions();
  }
};

const fetchQuestions = () => {
  fetch('http://localhost:3001/api/questions') // Оставляем как есть, если статистика возвращает вопросы
    .then(res => res.json())
    .then(setQuestions);
};
